    { id=20455, tab=3, tier=3, col=2, name="Serrated Blades", icon="inv_sword_17", maxRank=3, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Causes your attacks to ignore 186 of your target's Armor and increases the damage dealt by your Rupture ability by 10%. The amount of Armor reduced increases with your level.", "Causes your attacks to ignore 373 of your target's Armor and increases the damage dealt by your Rupture ability by 20%. The amount of Armor reduced increases with your level.", "Causes your attacks to ignore 560 of your target's Armor and increases the damage dealt by your Rupture ability by 30%. The amount of Armor reduced increases with your level." }, localized={deDE={name="Gezahnte Klingen", tooltip={ "Eure Angriffe ignorieren 186 Rüstung des Ziels und der Schaden Eurer Fähigkeit 'Blutung' wird um 10% erhöht. Die Menge der ignorierten Rüstung steigt mit Eurer Stufe.", "Eure Angriffe ignorieren 373 Rüstung des Ziels und der Schaden Eurer Fähigkeit 'Blutung' wird um 20% erhöht. Die Menge der ignorierten Rüstung steigt mit Eurer Stufe.", "Eure Angriffe ignorieren 560 Rüstung des Ziels und der Schaden Eurer Fähigkeit 'Blutung' wird um 30% erhöht. Die Menge der ignorierten Rüstung steigt mit Eurer Stufe." }}} },
    { id=20456, tab=3, tier=4, col=0, name="Heightened Senses", icon="ability_ambush", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases your Stealth detection and reduces the chance you are hit by spells and ranged attacks by 2%.", "Increases your Stealth detection and reduces the chance you are hit by spells and ranged attacks by 4%. More effective than Heightened Senses (Rank 1)." }, grant={ [1]=30894, [2]=30895 }, localized={deDE={name="Geschärfte Sinne", tooltip={ "Verbessert Eure Fähigkeit, verstohlene Gegner zu entdecken, und verringert die Chance, dass Ihr von Zaubern und Fernkampfangriffen getroffen werdet, um 2%.", "Verbessert Eure Fähigkeit, verstohlene Gegner zu entdecken, und verringert die Chance, dass Ihr von Zaubern und Fernkampfangriffen getroffen werdet, um 4%. Wirksamer als 'Geschärfte Sinne' (Rang 1)." }}} },
    { id=20457, tab=3, tier=4, col=1, name="Preparation", icon="spell_shadow_antishadow", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "When activated, this ability immediately finishes the cooldown on your Evasion, Sprint, Vanish, Cold Blood, Shadowstep and Premeditation abilities." }, grant={ [1]=947786 }, localized={deDE={name="Vorbereitung", tooltip={ "Beendet bei Aktivierung sofort die Abklingzeit Eurer Fähigkeiten 'Entrinnen', 'Sprinten', 'Verschwinden', 'Kaltblütigkeit', 'Schattenschritt' und 'Konzentration'." }}} },
    { id=20458, tab=3, tier=4, col=2, name="Dirty Deeds", icon="spell_shadow_summonsuccubus", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Reduces the Energy cost of your Cheap Shot and Garrote abilities by 10. Additionally, your special abilities cause 10% more damage against targets below 35% health.", "Reduces the Energy cost of your Cheap Shot and Garrote abilities by 20. Additionally, your special abilities cause 20% more damage against targets below 35% health." }, grant={ [1]=14082, [2]=14083 }, localized={deDE={name="Schmutzige Tricks", tooltip={ "Verringert die Energiekosten Eurer Fähigkeiten 'Fieser Trick' und 'Erdrosseln' um 10. Zusätzlich verursachen Eure Spezialfähigkeiten 10% mehr Schaden gegen Ziele mit weniger als 35% Gesundheit.", "Verringert die Energiekosten Eurer Fähigkeiten 'Fieser Trick' und 'Erdrosseln' um 20. Zusätzlich verursachen Eure Spezialfähigkeiten 20% mehr Schaden gegen Ziele mit weniger als 35% Gesundheit." }}} },
    { id=20459, tab=3, tier=4, col=3, name="Hemorrhage", icon="spell_shadow_lifedrain", maxRank=1, prereqTalent=20455, prereqPoints=20, wired=true, tooltip={ "An instant strike that deals 110% weapon damage and causes the target to hemorrhage, increasing any Physical damage dealt to the target by up to 13. Lasts 10 charges or 15 sec. Awards 1 combo point." }, grant={ [1]=16511 }, localized={deDE={name="Blutsturz", tooltip={ "Ein sofortiger Stoß, der 110% Waffenschaden verursacht und das Ziel stark bluten lässt. Erhöht jeglichen dem Ziel zugefügten körperlichen Schaden um bis zu 13. Hält 10 Aufladungen oder 15 Sek. lang an. Gewährt 1 Combopunkt." }}} },
    { id=20460, tab=3, tier=5, col=0, name="Master of Subtlety", icon="ability_rogue_masterofsubtlety", maxRank=3, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Attacks made while stealthed and for 6 seconds after breaking stealth cause an additional 4% damage.", "Attacks made while stealthed and for 6 seconds after breaking stealth cause an additional 7% damage.", "Attacks made while stealthed and for 6 seconds after breaking stealth cause an additional 10% damage." }, grant={ [1]=31221, [2]=31222, [3]=31223 }, localized={deDE={name="Meister des hinterhältigen Angriffs", tooltip={ "Angriffe im Verstohlenheitsmodus und in den ersten 6 Sekunden nach dem Verlassen dieses Modus verursachen 4% zusätzlichen Schaden.", "Angriffe im Verstohlenheitsmodus und in den ersten 6 Sekunden nach dem Verlassen dieses Modus verursachen 7% zusätzlichen Schaden.", "Angriffe im Verstohlenheitsmodus und in den ersten 6 Sekunden nach dem Verlassen dieses Modus verursachen 10% zusätzlichen Schaden." }}} },
    { id=20461, tab=3, tier=5, col=2, name="Deadliness", icon="inv_weapon_crossbow_11", maxRank=5, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Increases your attack power by 2%.", "Increases your attack power by 4%.", "Increases your attack power by 6%.", "Increases your attack power by 8%.", "Increases your attack power by 10%." }, grant={ [1]=30902, [2]=30903, [3]=30904, [4]=30905, [5]=30906 }, localized={deDE={name="Tödlichkeit", tooltip={ "Erhöht Eure Angriffskraft um 2%.", "Erhöht Eure Angriffskraft um 4%.", "Erhöht Eure Angriffskraft um 6%.", "Erhöht Eure Angriffskraft um 8%.", "Erhöht Eure Angriffskraft um 10%." }}} },
    { id=20462, tab=3, tier=6, col=0, name="Enveloping Shadows", icon="ability_rogue_envelopingshadows", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Increases your chance to avoid area of effect attacks by an additional 5%.", "Increases your chance to avoid area of effect attacks by an additional 10%.", "Increases your chance to avoid area of effect attacks by an additional 15%." }, localized={deDE={name="Einhüllende Schatten", tooltip={ "Erhöht Eure Chance, Angriffen mit Flächenwirkung zu entgehen, um zusätzliche 5%.", "Erhöht Eure Chance, Angriffen mit Flächenwirkung zu entgehen, um zusätzliche 10%.", "Erhöht Eure Chance, Angriffen mit Flächenwirkung zu entgehen, um zusätzliche 15%." }}} },
    { id=20463, tab=3, tier=6, col=1, name="Premeditation", icon="spell_shadow_possession", maxRank=1, prereqTalent=20457, prereqPoints=30, wired=true, tooltip={ "When used, adds 2 combo points to your target. You must add to or use those combo points within 10 sec or the combo points are lost." }, grant={ [1]=947787 }, localized={deDE={name="Konzentration", tooltip={ "Fügt Eurem Ziel bei Verwendung 2 Combopunkte hinzu. Ihr müsst diese Combopunkte innerhalb von 10 Sek. erweitern oder verwenden, sonst gehen sie verloren." }}} },
    { id=20464, tab=3, tier=6, col=2, name="Cheat Death", icon="ability_rogue_cheatdeath", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "You have a 33% chance that an attack which would otherwise kill you will instead reduce you to 10% of your maximum health. In addition, all damage taken will be reduced by up to 90% for 3 sec (modified by resilience). This effect cannot occur more than once per minute.", "You have a 66% chance that an attack which would otherwise kill you will instead reduce you to 10% of your maximum health. In addition, all damage taken will be reduced by up to 90% for 3 sec (modified by resilience). This effect cannot occur more than once per minute.", "You have a 100% chance that an attack which would otherwise kill you will instead reduce you to 10% of your maximum health. In addition, all damage taken will be reduced by up to 90% for 3 sec (modified by resilience). This effect cannot occur more than once per minute." }, grant={ [1]=31228, [2]=31229, [3]=31230 }, localized={deDE={name="Von der Schippe springen", tooltip={ "Ihr habt eine Chance von 33%, dass ein Angriff, der Euch sonst töten würde, Eure Gesundheit stattdessen auf 10% Eurer maximalen Gesundheit verringert. Zusätzlich wird jeglicher erlittener Schaden 3 Sek. lang um bis zu 90% verringert (durch Abhärtung modifiziert). Dieser Effekt kann höchstens einmal pro Minute auftreten.", "Ihr habt eine Chance von 66%, dass ein Angriff, der Euch sonst töten würde, Eure Gesundheit stattdessen auf 10% Eurer maximalen Gesundheit verringert. Zusätzlich wird jeglicher erlittener Schaden 3 Sek. lang um bis zu 90% verringert (durch Abhärtung modifiziert). Dieser Effekt kann höchstens einmal pro Minute auftreten.", "Ihr habt eine Chance von 100%, dass ein Angriff, der Euch sonst töten würde, Eure Gesundheit stattdessen auf 10% Eurer maximalen Gesundheit verringert. Zusätzlich wird jeglicher erlittener Schaden 3 Sek. lang um bis zu 90% verringert (durch Abhärtung modifiziert). Dieser Effekt kann höchstens einmal pro Minute auftreten." }}} },
    { id=20465, tab=3, tier=7, col=1, name="Sinister Calling", icon="ability_rogue_sinistercalling", maxRank=5, prereqTalent=20463, prereqPoints=35, wired=true, tooltip={ "Increases your total Agility by 3% and increases the percentage damage bonus of Backstab and Hemorrhage by an additional 1%.", "Increases your total Agility by 6% and increases the percentage damage bonus of Backstab and Hemorrhage by an additional 2%.", "Increases your total Agility by 9% and increases the percentage damage bonus of Backstab and Hemorrhage by an additional 3%.", "Increases your total Agility by 12% and increases the percentage damage bonus of Backstab and Hemorrhage by an additional 4%.", "Increases your total Agility by 15% and increases the percentage damage bonus of Backstab and Hemorrhage by an additional 5%." }, localized={deDE={name="Finstere Berufung", tooltip={ "Erhöht Eure gesamte Beweglichkeit um 3% und den prozentualen Schadensbonus von 'Meucheln' und 'Blutsturz' um zusätzliche 1%.", "Erhöht Eure gesamte Beweglichkeit um 6% und den prozentualen Schadensbonus von 'Meucheln' und 'Blutsturz' um zusätzliche 2%.", "Erhöht Eure gesamte Beweglichkeit um 9% und den prozentualen Schadensbonus von 'Meucheln' und 'Blutsturz' um zusätzliche 3%.", "Erhöht Eure gesamte Beweglichkeit um 12% und den prozentualen Schadensbonus von 'Meucheln' und 'Blutsturz' um zusätzliche 4%.", "Erhöht Eure gesamte Beweglichkeit um 15% und den prozentualen Schadensbonus von 'Meucheln' und 'Blutsturz' um zusätzliche 5%." }}} },
    { id=20466, tab=3, tier=8, col=1, name="Shadowstep", icon="ability_rogue_shadowstep", maxRank=1, prereqTalent=0, prereqPoints=40, wired=true, tooltip={ "Attempts to step through the shadows and reappear behind your enemy and increases movement speed by 70% for 3 sec. The damage of your next ability is increased by 20% and the threat caused is reduced by 50%. Lasts 10 sec." }, grant={ [1]=36554 }, localized={deDE={name="Schattenschritt", tooltip={ "Versucht, durch die Schatten hinter Euren Feind zu treten, und erhöht Eure Bewegungsgeschwindigkeit 3 Sek. lang um 70%. Der Schaden Eurer nächsten Fähigkeit wird um 20% erhöht und die erzeugte Bedrohung um 50% verringert. Hält 10 Sek. lang an." }}} },
